import json

def exists(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.exists', json.dumps({'path': path}))['returnValue']

def create_data(folder, name, class_path):
    path = folder + '/' + name
    if exists(path): return {'refPath': path + '.' + name}
    return execute_tool('editor_toolset.toolsets.data_asset.DataAssetTools.create', json.dumps({'folder_path': folder, 'asset_name': name, 'asset_type': {'refPath': class_path}}))['returnValue']

def create_bp(folder, name, class_path):
    path = folder + '/' + name
    if exists(path): return {'refPath': path + '.' + name}
    return execute_tool('editor_toolset.toolsets.blueprint.BlueprintTools.create', json.dumps({'folder_path': folder, 'asset_name': name, 'asset_type': {'refPath': class_path}}))['returnValue']

def duplicate(source, target):
    if exists(target): return 'existing'
    if not execute_tool('editor_toolset.toolsets.asset.AssetTools.duplicate', json.dumps({'path': source, 'new_path': target}))['returnValue']:
        raise RuntimeError('duplicate failed: ' + target)
    return 'created'

def create_widget(folder, name, parent):
    path = folder + '/' + name
    if exists(path): return {'refPath': path + '.' + name}
    return execute_tool('UMGToolSet.UMGToolSet.CreateWidgetBlueprint', json.dumps({'folderPath': folder, 'assetName': name, 'parentClass': {'refPath': parent}}))['returnValue']

def run():
    assets = {}
    assets['abilitySet'] = create_data('/ExtractionOps/AbilitySystem', 'AbilitySet_ExtractionCore', '/Script/LyraGame.LyraAbilitySet')
    item_names = ['DA_Ammo_Rifle','DA_Ammo_Shells','DA_Item_Medkit','DA_Valuable_ScrapMetal','DA_Valuable_PowerCell','DA_Valuable_CircuitBoard','DA_Valuable_OpticModule','DA_Valuable_ServoMotor','DA_Valuable_EncryptedDrive','DA_Valuable_ReactorCore','DA_Valuable_PrototypeChip']
    for name in item_names:
        assets[name] = create_data('/ExtractionOps/Items', name, '/Script/ExtractionOpsRuntime.ExtractionItemDefinition')
    assets['pickup'] = create_bp('/ExtractionOps/World/Loot', 'B_ExtractionWorldPickup', '/Script/ExtractionOpsRuntime.ExtractionWorldPickup')
    assets['container'] = create_bp('/ExtractionOps/World/Loot', 'B_ExtractionLootContainer', '/Script/ExtractionOpsRuntime.ExtractionLootContainer')
    assets['inventoryWidget'] = create_widget('/ExtractionOps/UI', 'W_ExtractionInventoryScreen', '/Script/ExtractionOpsRuntime.ExtractionInventoryWidget')
    assets['resultWidget'] = create_widget('/ExtractionOps/UI', 'W_ExtractionResultScreen', '/Script/ExtractionOpsRuntime.ExtractionResultWidget')
    assets['map'] = duplicate('/ShooterMaps/Maps/L_Convolution_Blockout', '/ExtractionOps/Maps/L_ExtractionTest')
    return {'assets': assets}
